{
  "sp": 5,
  "threshold": 3,
  "mode": "plan",
  "reason": "New generator + release-notes rewiring + CI guard + migration of a 2814-line file with many pinned downstream contracts (release_hygiene/publish_staging tests, ci.yml static job, root allow-list) — high integration surface."
}

// gh-2463 — changelog/ entries generator (`scripts/gen_changelog.dart`).
//
// Per-change entry files replace the single curated CHANGELOG.md as the
// merge surface: each PR adds `changelog/entries/<issue-or-pr>-<slug>.md`
// (YAML frontmatter `type`/`scope`/`issue` + 1–3 user-facing bullet lines)
// and NEVER edits CHANGELOG.md — zero conflicts by construction. The
// generator aggregates the pending entries into the release-notes body
// (byte-parity shape with the old curated `## Unreleased` body: flat
// bullets, deterministic order), regenerates the thin CHANGELOG.md index,
// and validates the entry set for CI.
import 'dart:io';

import 'package:test/test.dart';

final _tmpRoot = Directory.systemTemp.createTempSync('changelog-gen-');

late String _script;

ProcessResult _gen(List<String> args, String cwd) => Process.runSync(
  'dart',
  [_script, ...args],
  workingDirectory: cwd,
  stdoutEncoding: utf8,
  stderrEncoding: utf8,
);

String _fixture(String name) {
  final dir = Directory('${_tmpRoot.path}/$name')..createSync(recursive: true);
  Directory('${dir.path}/changelog/entries').createSync(recursive: true);
  return dir.path;
}

void _entry(String dir, String name, String body) {
  File('$dir/changelog/entries/$name').writeAsStringSync(body);
}

const _fm = '---\ntype: %T\nscope: %S\nissue: %I\n---\n';

String _entryBody(String type, String scope, String issue, String bullet) =>
  _fm
      .replaceFirst('%T', type)
      .replaceFirst('%S', scope)
      .replaceFirst('%I', issue) +
  '\n$bullet\n';

void main() {
  setUpAll(() {
    _script = File('scripts/gen_changelog.dart').absolute.path;
  });

  group('flat aggregate (release-notes body, parity shape)', () {
    test('bullets in (numeric-prefix, filename) order, nothing else', () {
      final dir = _fixture('flat-order');
      // Added out of order on purpose: numeric prefixes drive the order,
      // not file creation time.
      _entry(dir, '42-second-fix.md', _entryBody('fix', 'cli', '42', '- fix B'));
      _entry(dir, '7-first-feat.md', _entryBody('feat', 'ui', '7', '- feat A'));
      _entry(dir, '100-third-docs.md', _entryBody('docs', '', '', '- docs C'));
      final r = _gen(['--stdout'], dir);
      expect(r.exitCode, 0, reason: r.stderr);
      expect(r.stdout, '- feat A\n- fix B\n- docs C\n');
    });

    test('multi-line bullet bodies ride verbatim', () {
      final dir = _fixture('verbatim');
      _entry(
        dir,
        '9-multi.md',
        '---\ntype: fix\nissue: 9\n---\n\n- wrapped bullet line one\n  '
        'continuation stays glued to the bullet\n',
      );
      final r = _gen(['--stdout'], dir);
      expect(r.exitCode, 0, reason: r.stderr);
      expect(
        r.stdout,
        '- wrapped bullet line one\n  continuation stays glued to the bullet\n',
      );
    });

    test('empty entries dir → empty stdout, exit 0', () {
      final dir = _fixture('empty');
      final r = _gen(['--stdout'], dir);
      expect(r.exitCode, 0, reason: r.stderr);
      expect(r.stdout, '');
    });
  });

  group('issue dedupe (rework commits)', () {
    test('same issue twice → last-sorted file wins, loser reported', () {
      final dir = _fixture('dedupe');
      _entry(dir, '5-initial.md', _entryBody('fix', 'x', '5', '- initial text'));
      _entry(dir, '5-rework.md', _entryBody('fix', 'x', '5', '- reworked text'));
      final r = _gen(['--stdout'], dir);
      expect(r.exitCode, 0, reason: r.stderr);
      expect(r.stdout, '- reworked text\n');
      expect(r.stderr, contains('5-initial.md'));
      expect(r.stderr, contains('issue 5'));
    });

    test('entries WITHOUT an issue are never deduped', () {
      final dir = _fixture('dedupe-no-issue');
      _entry(dir, '1-a.md', '---\ntype: fix\n---\n\n- bullet A\n');
      _entry(dir, '2-b.md', '---\ntype: fix\n---\n\n- bullet B\n');
      final r = _gen(['--stdout'], dir);
      expect(r.exitCode, 0, reason: r.stderr);
      expect(r.stdout, '- bullet A\n- bullet B\n');
    });
  });

  group('--group-by-type', () {
    test('groups under fixed headings, unknown type lands in Other', () {
      final dir = _fixture('grouped');
      _entry(dir, '1-c.md', _entryBody('ci', '', '1', '- ci bullet'));
      _entry(dir, '2-a.md', _entryBody('feat', '', '2', '- feat bullet'));
      _entry(dir, '3-b.md', _entryBody('fix', '', '3', '- fix bullet'));
      _entry(dir, '4-d.md', '---\ntype: wip\n---\n\n- odd bullet\n');
      final r = _gen(['--group-by-type'], dir);
      expect(r.exitCode, 0, reason: r.stderr);
      expect(
        r.stdout,
        '### Features\n\n- feat bullet\n\n'
        '### Fixes\n\n- fix bullet\n\n'
        '### CI\n\n- ci bullet\n\n'
        '### Other\n\n- odd bullet\n',
      );
    });
  });

  group('--validate', () {
    test('a well-formed set passes (exit 0)', () {
      final dir = _fixture('validate-ok');
      _entry(dir, '11-ok.md', _entryBody('perf', 'redact', '11', '- fast path'));
      expect(_gen(['--validate'], dir).exitCode, 0);
    });

    test('missing type fails with ::error::', () {
      final dir = _fixture('validate-no-type');
      _entry(dir, '12-x.md', '---\nscope: cli\n---\n\n- bullet\n');
      final r = _gen(['--validate'], dir);
      expect(r.exitCode, 1);
      expect(r.stdout, contains('::error::'));
      expect(r.stdout, contains('12-x.md'));
    });

    test('unknown type fails naming the allowed set', () {
      final dir = _fixture('validate-bad-type');
      _entry(dir, '13-x.md', '---\ntype: sparkle\n---\n\n- bullet\n');
      final r = _gen(['--validate'], dir);
      expect(r.exitCode, 1);
      expect(r.stdout, contains('::error::'));
      expect(r.stdout, contains('sparkle'));
    });

    test('non-numeric filename prefix fails (the sort/dedupe key)', () {
      final dir = _fixture('validate-bad-name');
      _entry(dir, 'not-an-issue-slug.md', '---\ntype: fix\n---\n\n- bullet\n');
      final r = _gen(['--validate'], dir);
      expect(r.exitCode, 1);
      expect(r.stdout, contains('::error::'));
      expect(r.stdout, contains('not-an-issue-slug.md'));
    });

    test('empty body fails', () {
      final dir = _fixture('validate-empty-body');
      _entry(dir, '14-x.md', '---\ntype: fix\nissue: 14\n---\n\n\n');
      final r = _gen(['--validate'], dir);
      expect(r.exitCode, 1);
      expect(r.stdout, contains('::error::'));
    });

    test('missing frontmatter block fails', () {
      final dir = _fixture('validate-no-fm');
      _entry(dir, '15-x.md', '- just a bullet, no frontmatter\n');
      final r = _gen(['--validate'], dir);
      expect(r.exitCode, 1);
      expect(r.stdout, contains('::error::'));
    });

    test('more than 3 bullets warns but passes', () {
      final dir = _fixture('validate-long');
      _entry(
        dir,
        '16-x.md',
        '---\ntype: fix\n---\n\n- one\n- two\n- three\n- four\n',
      );
      final r = _gen(['--validate'], dir);
      expect(r.exitCode, 0, reason: r.stderr);
      expect(r.stdout, contains('::warning::'));
    });

    test('stray non-md file in entries/ is ignored, not an error', () {
      final dir = _fixture('validate-stray');
      _entry(dir, '17-x.md', '---\ntype: fix\n---\n\n- bullet\n');
      File('${dir.path}/changelog/entries/.gitkeep')
          .writeAsStringSync('');
      expect(_gen(['--validate'], dir).exitCode, 0);
    });
  });

  group('--write-changelog (thin generated index)', () {
    test('preamble + generated Unreleased + sorted archive index', () {
      final dir = _fixture('write');
      Directory('${dir.path}/changelog/archive').createSync();
      _entry(dir, '21-f.md', _entryBody('feat', 'release', '21', '- new flow'));
      for (final v in ['1.0.506', '1.0.551', 'legacy-unreleased']) {
        File('${dir.path}/changelog/archive/$v.md')
            .writeAsStringSync('## $v\n\n- old\n');
      }
      final r = _gen(['--write-changelog'], dir);
      expect(r.exitCode, 0, reason: r.stderr);
      final out = File('${dir.path}/CHANGELOG.md').readAsStringSync();
      // Generated marker so nobody hand-edits it.
      expect(out, contains('gen_changelog.dart --write-changelog'));
      expect(out, contains('DO NOT HAND-EDIT'));
      // The pending aggregate rides under ## Unreleased.
      expect(out, contains('## Unreleased'));
      expect(out, contains('- new flow'));
      // Archive index: version files newest-first, non-version last.
      final i551 = out.indexOf('changelog/archive/1.0.551.md');
      final i506 = out.indexOf('changelog/archive/1.0.506.md');
      final iLegacy = out.indexOf('changelog/archive/legacy-unreleased.md');
      expect(i551, greaterThan(0));
      expect(i506, greaterThan(i551), reason: '1.0.551 before 1.0.506');
      expect(iLegacy, greaterThan(i506), reason: 'non-version files last');
    });

    test('deterministic bytes across runs', () {
      final dir = _fixture('write-deterministic');
      Directory('${dir.path}/changelog/archive').createSync();
      _entry(dir, '22-f.md', _entryBody('feat', '', '22', '- x'));
      File('${dir.path}/changelog/archive/1.0.9.md').writeAsStringSync('# a\n');
      expect(_gen(['--write-changelog'], dir).exitCode, 0);
      final first = File('${dir.path}/CHANGELOG.md').readAsStringSync();
      expect(_gen(['--write-changelog'], dir).exitCode, 0);
      expect(File('${dir.path}/CHANGELOG.md').readAsStringSync(), first);
    });

    test('no pending entries → explicit placeholder, never an empty section', () {
      final dir = _fixture('write-empty');
      Directory('${dir.path}/changelog/archive').createSync();
      expect(_gen(['--write-changelog'], dir).exitCode, 0);
      final out = File('${dir.path}/CHANGELOG.md').readAsStringSync();
      expect(out, contains('## Unreleased'));
      expect(out, contains('changelog/entries/'));
    });
  });

  // gh-2463 AC1: two PRs touching the changelog in parallel must merge with
  // NO conflict — structurally, because each PR adds ITS OWN file and the
  // generator only READS the entries dir (it never writes into it), so the
  // aggregated view is the union of both PRs' files.
  group('AC1 — parallel PRs conflict-free by construction', () {
    test('two PRs’ files aggregate together; generator writes nothing into '
        'the shared tree', () {
      final dir = _fixture('ac1-parallel');
      // PR A's entry, already on main.
      _entry(dir, '31-a.md', _entryBody('feat', 'x', '31', '- PR A bullet'));
      // PR B's entry, landing in parallel.
      _entry(dir, '32-b.md', _entryBody('fix', 'y', '32', '- PR B bullet'));
      final before = _snapshot(dir);
      final r = _gen(['--stdout'], dir);
      expect(r.exitCode, 0, reason: r.stderr);
      expect(r.stdout, contains('- PR A bullet'));
      expect(r.stdout, contains('- PR B bullet'));
      // The only mutation a regeneration may make is CHANGELOG.md itself
      // (--write-changelog); plain aggregation is read-only.
      expect(_snapshot(dir), before);
    });
  });
}

Map<String, String> _snapshot(String dir) {
  final out = <String, String>{};
  for (final e in Directory(dir)
      .listSync(recursive: true)
      .whereType<File>()) {
    out[e.path] = e.readAsStringSync();
  }
  return out;
}

#!/usr/bin/env dart
// gh-2463 — changelog/ entries aggregator: the release-time replacement for
// the single curated CHANGELOG.md.
//
// Each PR adds ITS OWN entry file `changelog/entries/<issue-or-pr>-<slug>.md`
// (YAML frontmatter `type`/`scope`/`issue` + 1–3 user-facing bullet lines)
// and never edits CHANGELOG.md — parallel agents never touch a shared file,
// so the merge-conflict surface is gone by construction. This script:
//
//   --stdout           print the pending aggregate as flat bullets in
//                      (numeric-prefix, filename) order — the same shape the
//                      old curated `## Unreleased` body had, so
//                      scripts/release_notes.sh stays content-identical
//                      (default mode when no flag is given);
//   --group-by-type    same bullets grouped under type headings (human view);
//   --validate         validate every entry (frontmatter schema, filename
//                      convention, non-empty body) — CI static-gate input;
//   --write-changelog  regenerate the thin CHANGELOG.md index (preamble +
//                      generated `## Unreleased` + archive index). The file
//                      is generated-only: a CI guard rejects hand edits.
//
// Entry format:
//
//   ---
//   type: feat|fix|perf|docs|ci|other
//   scope: <short scope, optional>
//   issue: <issue or PR number, optional>
//   ---
//
//   - user-facing bullet (1–3 lines; the release notes body rides verbatim)
//
// Entries sharing a non-empty `issue` are rework duplicates: the LAST file in
// sort order wins, the loser is dropped with a stderr note (deterministic —
// no mtime/randomness in the output).
import 'dart:io';

const _types = <String>['feat', 'fix', 'perf', 'docs', 'ci', 'other'];

const _groupHeadings = <String, String>{
  'feat': 'Features',
  'fix': 'Fixes',
  'perf': 'Performance',
  'docs': 'Docs',
  'ci': 'CI',
  'other': 'Other',
};

final _fileNameRe = RegExp(r'^(\d+)-[a-z0-9-]+\.md$');
final _versionNameRe = RegExp(r'^\d+\.\d+\.\d+$');

String get _usage =>
    'usage: gen_changelog.dart [--stdout|--group-by-type|--validate|'
    '--write-changelog]  (entries dir: ./changelog/entries)';

/// One parsed entry file.
class Entry {
  Entry(this.file, this.sortKey, this.type, this.scope, this.issue, this.body);
  final String file; // path as reported in diagnostics
  final String sortKey; // filename — tie-break and dedupe winner key
  final int sortNum; // numeric filename prefix — primary sort
  final String type;
  final String scope;
  final String issue; // empty when absent
  final String body; // trimmed markdown bullets, verbatim
}

/// A structural problem in an entry file (::error:: in --validate).
class EntryProblem {
  EntryProblem(this.file, this.message);
  final String file;
  final String message;
}

void main(List<String> args) {
  final mode = _parseMode(args);
  final entriesDir = Directory('changelog/entries');
  final files = entriesDir.existsSync()
      ? entriesDir
          .listSync()
          .whereType<File>()
          .where((f) => f.path.endsWith('.md'))
          .map((f) => f.path)
          .toList()
      : <String>[];
  files.sort();

  final problems = <EntryProblem>[];
  final entries = <Entry>[];
  for (final path in files) {
    final name = path.split(Platform.pathSeparator).last;
    _parseEntry(path, name, problems) == null
        ? null
        : entries.add(_parseEntry(path, name, problems)!);
  }

  if (mode == Mode.validate) {
    _validate(entriesDir, files, problems, entries);
    return;
  }
  // Aggregate modes stop loudly on ANY broken entry: silently dropping one
  // would ship release notes missing that change (the release train must
  // notice at PR time, not in the published notes).
  if (problems.isNotEmpty) {
    for (final p in problems) {
      stderr.writeln('::error::${p.file}: ${p.message}');
    }
    stderr.writeln(
      'gen_changelog: ${problems.length} broken entry file(s) — '
      'run `dart scripts/gen_changelog.dart --validate` for the full list',
    );
    exit(1);
  }

  final kept = _dedupe(entries);
  if (mode == Mode.writeChangelog) {
    _writeChangelog(kept);
  } else {
    stdout.writeln(_aggregate(kept, grouped: mode == Mode.groupByType));
  }
}

Mode _parseMode(List<String> args) {
  final flags = args.where((a) => a.startsWith('--')).toSet();
  if (args.any((a) => a == '-h' || a == '--help')) {
    stdout.writeln(_usage);
    exit(0);
  }
  final positional = args.where((a) => !a.startsWith('--')).toList();
  if (positional.isNotEmpty || flags.difference(_knownFlags).isNotEmpty) {
    stderr.writeln(_usage);
    exit(2);
  }
  if (flags.length > 1) {
    stderr.writeln('gen_changelog: pick ONE mode flag; $_usage');
    exit(2);
  }
  if (flags.contains('--validate')) return Mode.validate;
  if (flags.contains('--group-by-type')) return Mode.groupByType;
  if (flags.contains('--write-changelog')) return Mode.writeChangelog;
  return Mode.stdoutMode; // --stdout and no-flag default
}

const _knownFlags = <String>{
  '--stdout',
  '--group-by-type',
  '--validate',
  '--write-changelog',
};

enum Mode { stdoutMode, groupByType, validate, writeChangelog }

Entry? _parseEntry(String path, String name, List<EntryProblem> problems) {
  final match = _fileNameRe.firstMatch(name);
  if (match == null) {
    problems.add(
      EntryProblem(
        name,
        'filename must be <issue-or-pr>-<slug>.md with a NUMERIC prefix '
        '(it is the sort + dedupe key), e.g. 2463-changelog-entries.md',
      ),
    );
    return null;
  }
  final text = File(path).readAsStringSync();
  if (!text.startsWith('---')) {
    problems.add(
      EntryProblem(name, 'missing YAML frontmatter block (--- ... ---)'),
    );
    return null;
  }
  final close = text.indexOf('\n---', 3);
  if (close < 0) {
    problems.add(EntryProblem(name, 'unterminated YAML frontmatter block'));
    return null;
  }
  final fm = text.substring(3, close);
  final body = text.substring(text.indexOf('\n', close + 1) + 1).trim();
  final meta = <String, String>{};
  for (final line in fm.split('\n')) {
    final idx = line.indexOf(':');
    if (idx <= 0) continue;
    meta[line.substring(0, idx).trim()] = line.substring(idx + 1).trim();
  }
  final type = meta['type'] ?? '';
  if (type.isEmpty) {
    problems.add(EntryProblem(name, "frontmatter needs a 'type:' field"));
    return null;
  }
  if (!_types.contains(type)) {
    problems.add(
      EntryProblem(name, "unknown type '$type' — allowed: ${_types.join(', ')}"),
    );
    return null;
  }
  if (body.isEmpty) {
    problems.add(
      EntryProblem(name, 'empty body — add 1–3 user-facing bullet lines'),
    );
    return null;
  }
  final bullets = body.split('\n').where((l) => l.startsWith('- ')).length;
  if (bullets > 3) {
    stderr.writeln(
      '::warning::$name: $bullets bullets — keep entries to 1–3 '
      'user-facing lines (long-form rationale belongs in the PR/ticket)',
    );
  }
  return Entry(
    name,
    name,
    int.parse(match.group(1)!),
    meta['scope'] ?? '',
    meta['issue'] ?? '',
    body,
  );
}

void _validate(
  Directory entriesDir,
  List<String> files,
  List<EntryProblem> problems,
  List<Entry> entries,
) {
  if (!entriesDir.existsSync()) {
    stdout.writeln(
      '::error::changelog/entries/ does not exist — create it with the '
      'first entry file (gh-2463 conventions: docs/agents/commits-releases.md)',
    );
    exit(1);
  }
  var ok = true;
  for (final p in problems) {
    stdout.writeln('::error::${p.file}: ${p.message}');
    ok = false;
  }
  // Duplicate issues are RESOLVED by the aggregator (last file wins), so not
  // an error — but the author must see that one of their files will be
  // dropped from the notes.
  final byIssue = <String, List<Entry>>{};
  for (final e in entries) {
    if (e.issue.isNotEmpty) (byIssue[e.issue] ??= []).add(e);
  }
  for (final issue in byIssue.keys.toList()..sort()) {
    final group = byIssue[issue]!..sort((a, b) => a.sortKey.compareTo(b.sortKey));
    if (group.length > 1) {
      final winner = group.last.sortKey;
      for (final loser in group.take(group.length - 1)) {
        stdout.writeln(
          '::warning::duplicate issue $issue: $winner wins, '
          '${loser.sortKey} will be dropped from the notes',
        );
      }
    }
  }
  if (!ok) exit(1);
  stdout.writeln(
    'changelog entries: ${entries.length} file(s) valid '
    '(${byIssue.keys.length} issue-keyed)',
  );
}

/// Rework dedupe: same non-empty issue → last file in sort order wins.
List<Entry> _dedupe(List<Entry> entries) {
  final sorted = entries.toList()
    ..sort((a, b) {
      final byNum = a.sortNum.compareTo(b.sortNum);
      return byNum != 0 ? byNum : a.sortKey.compareTo(b.sortKey);
    });
  final winnerOf = <String, Entry>{};
  final losers = <Entry>[];
  for (final e in sorted) {
    if (e.issue.isEmpty) continue;
    final incumbent = winnerOf[e.issue];
    if (incumbent == null) {
      winnerOf[e.issue] = e;
    } else {
      // Sorted order means the later file is the rework.
      losers.add(incumbent == e ? incumbent : incumbent);
      winnerOf[e.issue] = e;
    }
  }
  final kept = sorted.where((e) => !losers.contains(e)).toList();
  for (final loser in losers) {
    final winner = winnerOf[loser.issue]!;
    stderr.writeln(
      'gen_changelog: note: dropping ${loser.sortKey} — issue ${loser.issue} '
      'is already covered by ${winner.sortKey} (rework dedupe)',
    );
  }
  return kept;
}

String _aggregate(List<Entry> entries, {required bool grouped}) {
  if (!grouped) {
    return entries.map((e) => e.body).join('\n') +
        (entries.isEmpty ? '' : '\n');
  }
  final buf = StringBuffer();
  for (final type in _types) {
    final group = entries.where((e) => e.type == type).toList();
    if (group.isEmpty) continue;
    if (buf.isNotEmpty) buf.writeln();
    buf.writeln('### ${_groupHeadings[type]}');
    buf.writeln();
    buf.write(group.map((e) => e.body).join('\n') + '\n');
  }
  return buf.toString();
}

// ── --write-changelog: the thin generated index ─────────────────────────────

const _changelogPreamble = '''
<!-- GENERATED FILE — `dart scripts/gen_changelog.dart --write-changelog`.
     DO NOT HAND-EDIT: the CI changelog guard rejects direct edits
     (gh-2463). Regenerate instead. -->

Per-change entries live in `changelog/entries/` — one Markdown file per
change (`<issue-or-pr>-<slug>.md`, YAML frontmatter `type`/`scope`/`issue`
plus 1–3 user-facing bullet lines). Every PR adds ITS OWN entry file
instead of editing this file, so parallel changes never touch a shared
file (zero merge conflicts by construction). At release time the pending
entries aggregate into the `## Unreleased` section below and
`scripts/release_notes.sh` folds them into the release notes; versioned
history lives in `changelog/archive/` (one file per version — the
pre-1.0.506 tail stays in `CHANGELOG_ARCHIVE.md`). Conventions:
`docs/agents/commits-releases.md`.
''';

void _writeChangelog(List<Entry> kept) {
  final buf = StringBuffer('# Changelog\n\n$_changelogPreamble\n');
  buf.writeln('## Unreleased');
  buf.writeln();
  if (kept.isEmpty) {
    buf.writeln(
      '(Nothing pending — add `changelog/entries/<issue-or-pr>-<slug>.md` '
      'to your PR instead of editing this file.)',
    );
  } else {
    buf.write(_aggregate(kept, grouped: false));
  }
  buf.writeln();
  final archive = Directory('changelog/archive');
  if (archive.existsSync()) {
    buf.writeln('## Archive index');
    buf.writeln();
    for (final f in _archiveIndex(archive)) {
      buf.writeln('- [$f](changelog/archive/$f)');
    }
  }
  File('CHANGELOG.md').writeAsStringSync(buf.toString());
}

/// Version-named files first (newest version first, numeric compare —
/// lexicographic breaks at 1.0.100 vs 1.0.99), then non-version files
/// (legacy bodies) lexicographically.
List<String> _archiveIndex(Directory archive) {
  final names = archive
      .listSync()
      .whereType<File>()
      .map((f) => f.path.split(Platform.pathSeparator).last)
      .where((n) => n.endsWith('.md'))
      .toList();
  final versions = names.where((n) => _versionNameRe.hasMatch(n)).toList()
    ..sort((a, b) {
      List<int> v(String s) =>
          s.substring(0, s.length - 3).split('.').map(int.parse).toList();
      final va = v(a);
      final vb = v(b);
      for (var i = 0; i < 3; i++) {
        final c = vb[i].compareTo(va[i]); // desc
        if (c != 0) return c;
      }
      return b.compareTo(a);
    });
  final rest = names.where((n) => !_versionNameRe.hasMatch(n)).toList()..sort();
  return [...versions, ...rest];
}

