// gh-2463 — release_notes.sh consumes the changelog/entries aggregate.
//
// New preference level 1b in scripts/release_notes.sh: after the curated
// `## <version>` section, the pending changelog/entries/*.md aggregate (via
// scripts/gen_changelog.dart) becomes the release body; the legacy curated
// `## Unreleased` file body drops to level 1c and still wins over the
// conventional-commits fallback. AC2 parity: for the same set of changes the
// new flow (entry files) and the old flow (curated Unreleased body) yield
// the same bullet set.
import 'dart:io';

import 'package:test/test.dart';

final _tmpRoot = Directory.systemTemp.createTempSync('release-notes-entries-');

late String _notes;

ProcessResult _run(String version, String cwd) => Process.runSync(
  'bash',
  [_notes, version],
  workingDirectory: cwd,
  stdoutEncoding: utf8,
  stderrEncoding: utf8,
);

String _fixture(String name) {
  final dir = '${_tmpRoot.path}/$name';
  Directory(dir).createSync(recursive: true);
  return dir;
}

void _entry(String dir, String name, String bullet) {
  Directory('$dir/changelog/entries').createSync(recursive: true);
  File('$dir/changelog/entries/$name').writeAsStringSync(
    '---\ntype: fix\nissue: ${name.split('-').first}\n---\n\n$bullet\n',
  );
}

void main() {
  setUpAll(() {
    _notes = File('scripts/release_notes.sh').absolute.path;
  });

  test(
    'level 1b — pending entries aggregate into the release body',
    () {
      final dir = _fixture('entries-level');
      _entry(dir, '7-feat.md', '- entry feat bullet');
      _entry(dir, '12-fix.md', '- entry fix bullet');
      final r = _run('1.2.3', dir);
      expect(r.exitCode, 0, reason: r.stderr);
      expect(r.stdout, contains('- entry feat bullet'));
      expect(r.stdout, contains('- entry fix bullet'));
      // No conventional-commits fallback noise mixed in.
      expect(r.stdout, isNot(contains("What's changed")));
    },
  );

  test(
    'level 1 still wins — a curated ## <version> section outranks entries',
    () {
      final dir = _fixture('curated-wins');
      _entry(dir, '7-feat.md', '- entry bullet');
      File(
        '$dir/CHANGELOG.md',
      ).writeAsStringSync('# Changelog\n\n## 1.2.3\n\n- curated wins\n');
      final r = _run('1.2.3', dir);
      expect(r.exitCode, 0, reason: r.stderr);
      expect(r.stdout, contains('- curated wins'));
      expect(r.stdout, isNot(contains('- entry bullet')));
    },
  );

  test(
    'legacy level 1c — a curated ## Unreleased body still outranks commits '
    'but loses to entries',
    () {
      final dir = _fixture('legacy-unreleased');
      _entry(dir, '7-feat.md', '- entry bullet');
      File('$dir/CHANGELOG.md').writeAsStringSync(
        '# Changelog\n\n## Unreleased\n\n- legacy body bullet\n',
      );
      final r = _run('1.2.3', dir);
      expect(r.exitCode, 0, reason: r.stderr);
      expect(r.stdout, contains('- entry bullet'));
      expect(r.stdout, isNot(contains('- legacy body bullet')));
    },
  );

  test('no entries dir and no CHANGELOG.md → commit fallback unchanged', () {
    final dir = _fixture('fallback');
    Directory('$dir/changelog').createSync();
    Process.runSync(
      'git',
      ['init', '-q'],
      workingDirectory: dir,
    );
    Process.runSync(
      'git',
      ['-c', 'user.email=t@t', '-c', 'user.name=t', 'commit', '--allow-empty',
        '-qm', 'feat: fallback subject'],
      workingDirectory: dir,
    );
    final r = _run('1.2.3', dir);
    expect(r.exitCode, 0, reason: r.stderr);
    expect(r.stdout, contains('feat: fallback subject'));
  });

  test(
    'AC2 parity — same changes: old flow (curated Unreleased body) and new '
    'flow (entry files) produce the same bullet set',
    () {
      final bullets = '- fix: alpha one\n- fix: beta two\n- feat: gamma three\n';
      final oldDir = _fixture('parity-old');
      File(
        '$oldDir/CHANGELOG.md',
      ).writeAsStringSync('# Changelog\n\n## Unreleased\n\n$bullets\n');
      final newDir = _fixture('parity-new');
      _entry(newDir, '1-a.md', '- fix: alpha one');
      _entry(newDir, '2-b.md', '- fix: beta two');
      _entry(newDir, '3-c.md', '---\ntype: feat\nissue: 3\n---\n\n- feat: gamma three\n');
      final oldOut = _run('1.2.3', oldDir).stdout;
      final newOut = _run('1.2.3', newDir).stdout;
      Set<String> bulletSet(String out) => out
          .split('\n')
          .where((l) => l.startsWith('- '))
          .toSet();
      expect(bulletSet(newOut), bulletSet(oldOut));
      expect(bulletSet(newOut), isNotEmpty);
    },
  );
}

// gh-2463 — CI changelog entries guard (`scripts/check_changelog_entry.py`).
//
// The changelog merge surface is per-entry files now. The guard pins the
// two structural rules of the new flow:
//   1. a PR must ADD at least one `changelog/entries/<issue-or-pr>-<slug>.md`
//      file — or carry the `no-changelog` label (pull_request events only;
//      without PR label context the requirement degrades to a ::warning::
//      so dispatch re-validations never false-red);
//   2. NO PR may hand-edit the generated CHANGELOG.md, the root
//      CHANGELOG_ARCHIVE.md, or changelog/archive/** (hard everywhere).
// Wiring in the ci.yml `static` job is pinned too, and the repo allow-list
// must carry the new `changelog/` root dir.
import 'dart:io';

import 'package:test/test.dart';

final _tmpRoot = Directory.systemTemp.createTempSync('changelog-entry-guard-');

late String _guard;

ProcessResult _run(List<String> args, String cwd) => Process.runSync(
  'python3',
  [_guard, ...args],
  workingDirectory: cwd,
  stdoutEncoding: utf8,
  stderrEncoding: utf8,
);

/// Fixture repo with an initial commit so diffs have a base.
String _repo(String name) {
  final dir = '${_tmpRoot.path}/$name';
  Directory(dir).createSync(recursive: true);
  void git(List<String> args) => Process.runSync(
    'git',
    ['-c', 'user.email=t@t', '-c', 'user.name=t', ...args],
    workingDirectory: dir,
    stdoutEncoding: utf8,
    stderrEncoding: utf8,
  );
  git(['init', '-q', '-b', 'main']);
  File('$dir/CHANGELOG.md').writeAsStringSync('# Changelog\n');
  File('$dir/README.md').writeAsStringSync('# t\n');
  git(['add', '-A']);
  git(['commit', '-qm', 'init']);
  return dir;
}

void _commit(String dir, String msg) => Process.runSync(
  'git',
  ['-c', 'user.email=t@t', '-c', 'user.name=t', 'commit', '-qm', msg],
  workingDirectory: dir,
);

String _addEntry(String dir, String name) {
  final path = '$dir/changelog/entries/$name';
  File(path).parent.createSync(recursive: true);
  File(path).writeAsStringSync(
    '---\ntype: fix\nissue: ${name.split('-').first}\n---\n\n- bullet\n',
  );
  return path;
}

void main() {
  setUpAll(() {
    _guard = File('scripts/check_changelog_entry.py').absolute.path;
  });

  test('PR adding an entry file and nothing else → pass', () {
    final dir = _repo('entry-added');
    _addEntry(dir, '100-fix.md');
    Process.runSync('git', ['add', '-A'], workingDirectory: dir);
    _commit(dir, 'feat: x');
    final r = _run(['--base', 'HEAD~1', '--head', 'HEAD', '--pr-context', 'true'], dir);
    expect(r.exitCode, 0, reason: '${r.stdout}${r.stderr}');
  });

  test('PR editing CHANGELOG.md directly → ::error:: and exit 1', () {
    final dir = _repo('changelog-edit');
    _addEntry(dir, '101-fix.md'); // has an entry, still forbidden
    File('$dir/CHANGELOG.md').writeAsStringSync('# hand edited\n');
    Process.runSync('git', ['add', '-A'], workingDirectory: dir);
    _commit(dir, 'edit');
    final r = _run(['--base', 'HEAD~1', '--head', 'HEAD', '--pr-context', 'true'], dir);
    expect(r.exitCode, 1);
    expect(r.stdout, contains('::error::'));
    expect(r.stdout, contains('CHANGELOG.md'));
  });

  test('PR touching changelog/archive/** → exit 1', () {
    final dir = _repo('archive-edit');
    File('$dir/changelog/archive/1.0.551.md').parent.createSync(recursive: true);
    File('$dir/changelog/archive/1.0.551.md').writeAsStringSync('## 1.0.551\n');
    Process.runSync('git', ['add', '-A'], workingDirectory: dir);
    _commit(dir, 'archive');
    final r = _run(['--base', 'HEAD~1', '--head', 'HEAD', '--pr-context', 'true'], dir);
    expect(r.exitCode, 1);
    expect(r.stdout, contains('::error::'));
    expect(r.stdout, contains('changelog/archive'));
  });

  test('no entry file and no label (pr context) → exit 1', () {
    final dir = _repo('no-entry');
    File('$dir/lib.dart').writeAsStringSync('void f() {}\n');
    Process.runSync('git', ['add', '-A'], workingDirectory: dir);
    _commit(dir, 'code');
    final r = _run(['--base', 'HEAD~1', '--head', 'HEAD', '--pr-context', 'true'], dir);
    expect(r.exitCode, 1);
    expect(r.stdout, contains('::error::'));
    expect(r.stdout, contains('no-changelog'));
  });

  test('no-changelog label waives the entry requirement', () {
    final dir = _repo('labeled');
    File('$dir/lib.dart').writeAsStringSync('void f() {}\n');
    Process.runSync('git', ['add', '-A'], workingDirectory: dir);
    _commit(dir, 'code');
    final r = _run(
      ['--base', 'HEAD~1', '--head', 'HEAD', '--pr-context', 'true',
        '--labels', 'no-changelog,ci'],
      dir,
    );
    expect(r.exitCode, 0, reason: '${r.stdout}${r.stderr}');
  });

  test('an unrelated label does NOT waive the requirement', () {
    final dir = _repo('wrong-label');
    File('$dir/lib.dart').writeAsStringSync('void f() {}\n');
    Process.runSync('git', ['add', '-A'], workingDirectory: dir);
    _commit(dir, 'code');
    final r = _run(
      ['--base', 'HEAD~1', '--head', 'HEAD', '--pr-context', 'true',
        '--labels', 'some-other-label'],
      dir,
    );
    expect(r.exitCode, 1);
  });

  test(
    'no entry and NO pr-context (dispatch/push arm) → ::warning::, exit 0',
    () {
      final dir = _repo('dispatch');
      File('$dir/lib.dart').writeAsStringSync('void f() {}\n');
      Process.runSync('git', ['add', '-A'], workingDirectory: dir);
      _commit(dir, 'code');
      final r = _run(['--base', 'HEAD~1', '--head', 'HEAD'], dir);
      expect(r.exitCode, 0, reason: '${r.stdout}${r.stderr}');
      expect(r.stdout, contains('::warning::'));
    },
  );

  test('empty diff (already-merged push) → pass', () {
    final dir = _repo('empty-diff');
    final r = _run(['--base', 'HEAD', '--head', 'HEAD', '--pr-context', 'true'], dir);
    expect(r.exitCode, 0, reason: '${r.stdout}${r.stderr}');
  });

  test('added-but-deleted entry net change still counts as added', () {
    // A PR that adds an entry file and ALSO deletes a DIFFERENT entry file
    // (housekeeping of its own consumed entry) satisfies the requirement.
    final dir = _repo('housekeeping');
    _addEntry(dir, '200-keep.md');
    _addEntry(dir, '190-consumed.md');
    Process.runSync('git', ['add', '-A'], workingDirectory: dir);
    _commit(dir, 'entries');
    File('$dir/changelog/entries/190-consumed.md').deleteSync();
    _addEntry(dir, '210-new.md');
    Process.runSync('git', ['add', '-A'], workingDirectory: dir);
    _commit(dir, 'housekeep');
    final r = _run(['--base', 'HEAD~1', '--head', 'HEAD', '--pr-context', 'true'], dir);
    expect(r.exitCode, 0, reason: '${r.stdout}${r.stderr}');
  });

  test('ci.yml static job wires the guard (self-test + real run)', () {
    final wf = File('.github/workflows/ci.yml').readAsStringSync();
    expect(wf, contains('scripts/check_changelog_entry.py --self-test'));
    expect(wf, contains('python3 scripts/check_changelog_entry.py'));
  });

  test('the real repo passes the guard (allow-list carries changelog/)', () {
    final r = Process.runSync(
      'python3',
      [File('scripts/check_root_allowlist.py').absolute.path],
      stdoutEncoding: utf8,
      stderrEncoding: utf8,
    );
    expect(r.exitCode, 0, reason: '${r.stdout}${r.stderr}');
  });
}

